-- AQUANEST – Ensiklopedia Biota Laut Nusantara
-- Database: aquanest_db (MySQL / MariaDB for XAMPP & Laragon)
CREATE DATABASE IF NOT EXISTS aquanest_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE aquanest_db;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS conservation_tips, quiz_results, quiz_questions, quizzes, educational_materials, species, conservation_status, habitats, categories, users;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  email VARCHAR(160) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  role ENUM('user','admin') NOT NULL DEFAULT 'user',
  avatar_initials VARCHAR(8) NOT NULL DEFAULT 'AN',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE categories (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  slug VARCHAR(120) NOT NULL UNIQUE,
  description TEXT NOT NULL
) ENGINE=InnoDB;
CREATE TABLE habitats (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  slug VARCHAR(120) NOT NULL UNIQUE,
  depth_range VARCHAR(80) NOT NULL,
  temperature_range VARCHAR(80) NOT NULL,
  description TEXT NOT NULL,
  image_url VARCHAR(255) NOT NULL,
  key_locations VARCHAR(255) NOT NULL
) ENGINE=InnoDB;
CREATE TABLE conservation_status (
  id INT AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(8) NOT NULL UNIQUE,
  label_id VARCHAR(80) NOT NULL,
  label_en VARCHAR(80) NOT NULL,
  severity_level INT NOT NULL,
  description TEXT NOT NULL
) ENGINE=InnoDB;
CREATE TABLE species (
  id INT AUTO_INCREMENT PRIMARY KEY,
  common_name VARCHAR(160) NOT NULL,
  scientific_name VARCHAR(180) NOT NULL,
  slug VARCHAR(160) NOT NULL UNIQUE,
  category_id INT NOT NULL,
  habitat_id INT NOT NULL,
  conservation_status_id INT NOT NULL,
  depth_min_m INT NOT NULL DEFAULT 0,
  depth_max_m INT NOT NULL DEFAULT 50,
  length_cm INT NOT NULL DEFAULT 50,
  diet VARCHAR(255) NOT NULL,
  distribution_indonesia VARCHAR(255) NOT NULL,
  summary TEXT NOT NULL,
  description TEXT NOT NULL,
  conservation_notes TEXT NOT NULL,
  image_url VARCHAR(255) NOT NULL,
  is_featured TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_sp_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sp_habitat FOREIGN KEY (habitat_id) REFERENCES habitats(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sp_status FOREIGN KEY (conservation_status_id) REFERENCES conservation_status(id) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE educational_materials (
  id INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  slug VARCHAR(200) NOT NULL UNIQUE,
  topic VARCHAR(120) NOT NULL,
  reading_minutes INT NOT NULL DEFAULT 5,
  author_name VARCHAR(120) NOT NULL,
  summary TEXT NOT NULL,
  content LONGTEXT NOT NULL,
  image_url VARCHAR(255) NOT NULL,
  published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE quizzes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(180) NOT NULL,
  slug VARCHAR(180) NOT NULL UNIQUE,
  description TEXT NOT NULL,
  difficulty VARCHAR(40) NOT NULL DEFAULT 'Menengah',
  time_limit_minutes INT NOT NULL DEFAULT 10,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE quiz_questions (
  id INT AUTO_INCREMENT PRIMARY KEY,
  quiz_id INT NOT NULL,
  question_text TEXT NOT NULL,
  option_a VARCHAR(255) NOT NULL,
  option_b VARCHAR(255) NOT NULL,
  option_c VARCHAR(255) NOT NULL,
  option_d VARCHAR(255) NOT NULL,
  correct_option ENUM('A','B','C','D') NOT NULL,
  explanation TEXT NOT NULL,
  CONSTRAINT fk_qq_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE quiz_results (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  quiz_id INT NOT NULL,
  score INT NOT NULL,
  total_questions INT NOT NULL,
  percentage INT NOT NULL,
  completed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_qr_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_qr_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE
) ENGINE=InnoDB;

INSERT INTO users (id, name, email, password_hash, role, avatar_initials) VALUES (1, 'Dr. Nabila Pratiwi (Kurator)', 'admin@aquanest.id', '$2b$10$DQq/kJxg67PawsYc.yds/.WG8O0/3/sTSdCqMZ6FFRQ9Juno6VbIS', 'admin', 'NP');
INSERT INTO users (id, name, email, password_hash, role, avatar_initials) VALUES (2, 'Raka Samudra', 'penjelajah@aquanest.id', '$2b$10$..jSQCzQ8xhTkwk2tp7B/uncWipAVEBM1MUcUeJHnVBoy/MnPJQ3S', 'user', 'RS');
INSERT INTO categories (id, name, slug, description) VALUES (1, 'Ikan Bertulang Sejati', 'ikan-bertulang', 'Beragam spesies ikan karang dan pelagis penghuni perairan Nusantara.');
INSERT INTO categories (id, name, slug, description) VALUES (2, 'Hiu & Pari', 'hiu-dan-pari', 'Kelompok ikan bertulang rawan (Elasmobranchii) penjaga keseimbangan puncak rantai makanan laut.');
INSERT INTO categories (id, name, slug, description) VALUES (3, 'Mamalia & Reptil Laut', 'mamalia-reptil', 'Penyu laut, lumba-lumba, dan dugong yang bernapas dengan paru-paru di perairan tropis.');
INSERT INTO categories (id, name, slug, description) VALUES (4, 'Invertebrata & Moluska', 'invertebrata-moluska', 'Gurita, cumi-cumi, kima raksasa, krustasea, dan ekinodermata unik dasar laut.');
INSERT INTO categories (id, name, slug, description) VALUES (5, 'Karang & Pembentuk Terumbu', 'karang-terumbu', 'Organisme pembangun struktur terumbu karang di jantung Segitiga Terumbu Karang Dunia.');
INSERT INTO habitats (id, name, slug, depth_range, temperature_range, description, image_url, key_locations) VALUES (1, 'Terumbu Karang', 'terumbu-karang', '1 – 45 m', '26 – 30 °C', 'Ekosistem laut dangkal paling produktif di dunia. Indonesia berada di pusat Segitiga Terumbu Karang (Coral Triangle) yang menaungi lebih dari 76% spesies karang pembentuk terumbu dunia.', 'assets/images/habitats/terumbu-karang.jpg', 'Raja Ampat, Bunaken, Wakatobi, Komodo, Derawan');
INSERT INTO habitats (id, name, slug, depth_range, temperature_range, description, image_url, key_locations) VALUES (2, 'Padang Lamun', 'padang-lamun', '0,5 – 15 m', '27 – 31 °C', 'Hamparan tumbuhan berbunga laut (seagrass) di perairan pesisir jernih yang menjadi daerah asuhan ikan muda, penstabil sedimen, penyimpan karbon biru, dan sumber pakan utama dugong serta penyu hijau.', 'assets/images/habitats/padang-lamun.jpg', 'Kepulauan Riau, Derawan, Taka Bonerate, Sulawesi Utara');
INSERT INTO habitats (id, name, slug, depth_range, temperature_range, description, image_url, key_locations) VALUES (3, 'Hutan Mangrove', 'hutan-mangrove', '0 – 3 m (Pasang Surut)', '25 – 32 °C', 'Ekosistem peralihan darat-laut dengan sistem perakaran napas yang meredam gelombang tsunami, menyaring sedimen pesisir, serta menjadi tempat berlindung kepiting bakau dan benih ikan karang.', 'assets/images/habitats/hutan-mangrove.jpg', 'Papua Barat, Kalimantan Timur, Taman Nasional Sembilang, Bali');
INSERT INTO habitats (id, name, slug, depth_range, temperature_range, description, image_url, key_locations) VALUES (4, 'Laut Dalam & Pelagis', 'laut-dalam', '50 – 1.500+ m', '4 – 24 °C', 'Zona laut terbuka hingga lereng benua dalam dengan arus lintas Indonesia (Arlindo) yang kaya nutrien, menjadi jalur migrasi hiu paus, tuna, pari manta, ikan mola-mola, dan nautilus.', 'assets/images/habitats/laut-dalam.jpg', 'Selat Alor, Laut Banda, Nusa Penida, Teluk Cenderawasih');
INSERT INTO conservation_status (id, code, label_id, label_en, severity_level, description) VALUES (1, 'CR', 'Kritis', 'Critically Endangered', 5, 'Menghadapi risiko kepunahan amat sangat tinggi di alam liar dalam waktu dekat.');
INSERT INTO conservation_status (id, code, label_id, label_en, severity_level, description) VALUES (2, 'EN', 'Terancam', 'Endangered', 4, 'Populasi mengalami penurunan drastis dan berisiko tinggi punah di alam liar.');
INSERT INTO conservation_status (id, code, label_id, label_en, severity_level, description) VALUES (3, 'VU', 'Rentan', 'Vulnerable', 3, 'Menghadapi risiko kepunahan tinggi akibat hilangnya habitat dan eksploitasi.');
INSERT INTO conservation_status (id, code, label_id, label_en, severity_level, description) VALUES (4, 'NT', 'Hampir Terancam', 'Near Threatened', 2, 'Berpotensi masuk kategori terancam jika tekanan ekologis tidak dikendalikan.');
INSERT INTO conservation_status (id, code, label_id, label_en, severity_level, description) VALUES (5, 'LC', 'Risiko Rendah', 'Least Concern', 1, 'Populasi relatif stabil dan tersebar luas, namun tetap membutuhkan pengelolaan lestari.');
INSERT INTO conservation_status (id, code, label_id, label_en, severity_level, description) VALUES (6, 'DD', 'Kurang Data', 'Data Deficient', 2, 'Belum cukup data lapangan untuk menilai risiko kepunahan secara akurat.');
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (1, 'Hiu Paus', 'Rhincodon typus', 'hiu-paus', 2, 4, 2, 0, 1900, 1200, 'Plankton, krill, telur ikan, dan ikan pelagis kecil (filter feeder)', 'Teluk Cenderawasih (Papua), Teluk Saleh (NTB), Gorontalo, Probolinggo', 'Ikan terbesar di dunia yang jinak dan menyaring plankton di perairan hangat Nusantara.', 'Hiu paus (Rhincodon typus) adalah ikan bertulang rawan terbesar yang masih hidup di samudra. Meski tubuhnya dapat mencapai panjang lebih dari 12 meter dengan pola totol putih khas bak rasi bintang, biota ini sepenuhnya jinak dan hanya memakan plankton serta ikan kecil dengan cara menyaring air laut.', 'Dilindungi penuh di Indonesia melalui Keputusan Menteri Kelautan dan Perikanan No. 18 Tahun 2013. Pariwisata pengamatan hiu paus berbasis etika di Teluk Cenderawasih dan Gorontalo terus diawasi agar tidak mengganggu jalur makan alaminya.', 'assets/images/species/hiu-paus.jpg', 1);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (2, 'Penyu Hijau', 'Chelonia mydas', 'penyu-hijau', 3, 2, 2, 1, 40, 120, 'Lamun dan alga laut (herbivora saat dewasa)', 'Kepulauan Derawan, Sukamade (Banyuwangi), Pangumbahan, Bali, Papua', 'Penyu laut pemakan lamun yang bermigrasi ribuan kilometer kembali ke pantai kelahirannya.', 'Penyu hijau dinamai bukan dari warna tempurungnya yang kecokelatan-zaitun, melainkan dari warna jaringan lemak kehijauan di bawah karapas akibat diet lamun dan rumput laut. Penyu ini berperan menjaga kesehatan padang lamun Nusantara dengan memangkas helai lamun tua secara teratur.', 'Seluruh spesies penyu laut dilindungi penuh berdasarkan PP No. 7 Tahun 1999. Ancaman utama meliputi perburuan telur, sampah plastik yang menyerupai ubur-ubur, dan terjerat jaring insang.', 'assets/images/species/penyu-hijau.jpg', 1);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (3, 'Dugong', 'Dugong dugon', 'dugong', 3, 2, 3, 1, 20, 300, 'Lamun dasar laut (herbivora laut sejati)', 'Kepulauan Riau, Alor, Tolitoli, Pulau Biak, Taman Nasional Ujung Kulon', 'Mamalia laut pemalu penjaga ekosistem padang lamun tropis Indonesia.', 'Dugong adalah satu-satunya mamalia laut herbivora sejati di perairan Indo-Pasifik. Tubuhnya gempal berwarna abu-abu kecokelatan dengan ekor bercabang menyerupai lumba-lumba serta moncong menghadap ke bawah untuk mencabut rimpang lamun dari dasar pasir.', 'Populasi dugong sangat rentan karena laju reproduksinya lambat (satu anak tiap 3–7 tahun) dan ketergantungan mutlak pada padang lamun yang kini terancam reklamasi dan sedimentasi pesisir.', 'assets/images/species/dugong.jpg', 1);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (4, 'Pari Manta Samudra', 'Mobula birostris', 'pari-manta', 2, 4, 2, 0, 120, 700, 'Zooplankton dan larva krustasea laut terbuka', 'Raja Ampat, Nusa Penida, Komodo, Sangalaki (Derawan)', 'Pari raksasa dengan rentang sirip hingga 7 meter yang meluncur anggun di arus Nusantara.', 'Pari manta samudra memiliki otak terbesar di antara seluruh spesies ikan dan dikenal cerdas serta mudah berinteraksi di stasiun pembersihan karang. Pola bercak hitam di perut setiap individu bersifat unik seperti sidik jari manusia, memudahkan peneliti memantau migrasi antar pulau.', 'Indonesia merupakan kawasan suaka pari manta terbesar di dunia sejak ditetapkan perlindungan penuh pada tahun 2014 melalui Kepmen KP No. 4/2014 untuk menghentikan perdagangan tapis insang.', 'assets/images/species/pari-manta.jpg', 1);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (5, 'Ikan Badut', 'Amphiprion ocellaris', 'ikan-badut', 1, 1, 5, 1, 15, 11, 'Copepoda, alga mikro, dan sisa makanan anemon inang', 'Seluruh terumbu karang Indonesia: Bunaken, Wakatobi, Bali, Maluku, Raja Ampat', 'Ikan karang oranye-putih yang hidup bersimbiosis mutualisme dengan anemon laut.', 'Ikan badut memiliki lapisan lendir khusus pada kulitnya yang membuatnya kebal terhadap sengatan nematocyst tentakel anemon laut. Sebagai imbalan perlindungan dari predator, ikan badut membersihkan parasit pada anemon dan menyediakan nutrien dari kotorannya.', 'Meskipun berstatus Risiko Rendah, penangkapan berlebih untuk perdagangan ikan hias dan pemutihan karang (coral bleaching) mengancam ketersediaan anemon inang di beberapa lokasi wisata selam.', 'assets/images/species/ikan-badut.jpg', 1);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (6, 'Kuda Laut Kuning', 'Hippocampus kuda', 'kuda-laut', 1, 2, 3, 1, 20, 17, 'Krustasea kecil, amfipoda, dan larva ikan hidup', 'Teluk Lampung, Kepulauan Seribu, Sulawesi Selatan, Maluku, Nusa Tenggara', 'Ikan bertubuh unik dengan ekor prehensil di mana pejantan mengerami telur di kantung perutnya.', 'Kuda laut kuning hidup bersembunyi di antara padang lamun, alga Sargassum, dan akar mangrove. Mereka berenang tegak menggunakan sirip punggung kecil yang bergetar cepat dan mengaitkan ekor pada lamun agar tidak terbawa arus pasang.', 'Masuk kategori Rentan IUCN dan tercatat dalam Apendiks II CITES karena tingginya eksploitasi untuk pengobatan tradisional kering serta degradasi padang lamun.', 'assets/images/species/kuda-laut.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (7, 'Lumba-lumba Pemintal', 'Stenella longirostris', 'lumba-lumba', 3, 4, 5, 0, 300, 210, 'Ikan pelagis kecil, cumi-cumi, dan krustasea malam', 'Lovina (Bali), Laut Sawu, Alor, Wakatobi, Laut Banda, Kalimantan Timur', 'Lumba-lumba akrobatik Nusantara yang terkenal dengan lompatan berputar di udara.', 'Lumba-lumba pemintal sering terlihat beriringan dalam kawanan besar di perairan dalam dekat pulau vulkanik Indonesia. Mereka aktif berburu pada malam hari mengikuti migrasi vertikal organisme mesopelagis dan beristirahat di teluk tenang pada pagi hari.', 'Dilindungi undang-undang nasional sebagai mamalia laut. Pengelolaan wisata pengamatan lumba-lumba di Lovina dan Laut Sawu menekankan jarak aman perahu agar tidak memicu stres akustik.', 'assets/images/species/lumba-lumba.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (8, 'Napoleon Wrasse', 'Cheilinus undulatus', 'napoleon-wrasse', 1, 1, 2, 2, 60, 200, 'Moluska bercangkang keras, bulu babi, dan bintang laut mahkota berduri', 'Raja Ampat, Maratua, Wakatobi, Anambas, Kepulauan Banda', 'Ikan karang raksasa berjambul dahi ikonik yang mengendalikan populasi hama karang.', 'Napoleon wrasse atau ikan maming adalah anggota keluarga wrasse terbesar di dunia. Selain warna biru-hijau metalik dan tonjolan khas di dahi, ikan ini berperan vital secara ekologis karena mampu memangsa bintang laut mahkota berduri (Acanthaster planci) pemakan polip karang.', 'Terancam punah akibat tingginya nilai jual hidup di pasar ekspor restoran mewah serta laju pertumbuhan yang sangat lambat untuk mencapai kematangan seksual.', 'assets/images/species/napoleon-wrasse.jpg', 1);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (9, 'Pari Totol Biru', 'Taeniura lymma', 'pari-totol-biru', 2, 1, 5, 1, 30, 70, 'Cacing polikaeta, udang, kepiting kecil, dan moluska pasir', 'Bunaken, Tulamben (Bali), Komodo, Karimunjawa, Papua', 'Pari karang bertubuh bundar dengan bintik biru elektrik terang yang mencolok di dasar pasir.', 'Pari totol biru mudah dikenali melalui cakram tubuh oval berwarna cokelat keemasan berhias totol biru terang dan dua garis biru di sepanjang ekornya. Pada siang hari ia kerap beristirahat di bawah ceruk karang meja dan keluar berburu saat pasang naik.', 'Memiliki dua duri berbisa di pangkal ekor sebagai pertahanan diri. Meski populasinya masih cukup baik, kerusakan terumbu karang dangkal mengurangi area berlindungnya.', 'assets/images/species/pari-totol-biru.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (10, 'Hiu Martil Bergerigi', 'Sphyrna lewini', 'hiu-martil', 2, 4, 1, 5, 500, 380, 'Ikan bertulang, cumi-cumi, dan pari kecil', 'Laut Banda, Sulawesi Utara, Selat Makassar, Laut Arafura, Maluku', 'Predator pelagis bermata di ujung kepala pipih berbentuk palu yang kini berstatus Kritis.', 'Bentuk kepala cephalofoil unik pada hiu martil memberi medan pandang binokular 360 derajat serta memperluas sebaran reseptor elektromagnetik (ampullae of Lorenzini) untuk mendeteksi mangsa yang bersembunyi di balik pasir laut.', 'Berstatus Kritis (Critically Endangered) akibat penangkapan target maupun tangkapan sampingan untuk diambil siripnya. Indonesia memberlakukan larangan ekspor sirip hiu martil sesuai regulasi CITES.', 'assets/images/species/hiu-martil.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (11, 'Hiu Karang Sirip Hitam', 'Carcharhinus melanopterus', 'hiu-karang', 2, 1, 3, 1, 75, 160, 'Ikan karang kecil, sefalopoda, dan krustasea laguna', 'Raja Ampat, Gili Trawangan, Pulau Weh, Derawan, Nusa Penida', 'Penjaga terumbu karang dangkal yang mudah dikenali dari ujung sirip punggung hitam tegas.', 'Hiu karang sirip hitam kerap berpatroli di laguna dangkal dan tubir terumbu karang. Meski bertampang predator gesit, hiu ini umumnya pemalu terhadap penyelam dan menjaga kesehatan terumbu dengan memangsa ikan sakit atau lemah.', 'Rentan terhadap hilangnya habitat laguna pesisir dan penangkapan jaring pantai. Keberadaannya menjadi indikator penting ekosistem karang yang sehat.', 'assets/images/species/hiu-karang.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (12, 'Ikan Mola-mola', 'Mola alexandrini', 'ikan-mola-mola', 1, 4, 6, 10, 480, 300, 'Ubur-ubur, salpa, dan organisme gelatinosa pelagis', 'Nusa Penida (Crystal Bay), Selat Lombok, Laut Banda, Alor', 'Ikan bertulang terberat di dunia yang naik ke perairan dangkal Nusa Penida untuk berjemur dan dibersihkan parasitnya.', 'Ikan mola-mola memiliki bentuk tubuh cakram pipih raksasa tanpa sirip ekor sejati (digantikan clavus). Pada musim arus dingin Juli–Oktober di Nusa Penida, mola-mola naik dari kedalaman menuju stasiun pembersihan karang agar ikan kepe-kepe membersihkan parasit kulitnya.', 'Sering terdampak tangkapan sampingan jaring insang hanyut dan konsumsi kantong plastik yang dikira ubur-ubur. Kode etik penyelaman Nusa Penida mengatur jarak aman agar mola-mola tidak stres.', 'assets/images/species/ikan-mola-mola.jpg', 1);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (13, 'Ikan Mandarin', 'Synchiropus splendidus', 'ikan-mandarin', 1, 1, 5, 1, 18, 7, 'Cacing kecil, protozoa, dan krustasea mikro di patahan karang', 'Selat Lembeh, Teluk Ambon, Raja Ampat, Banggai, Bali Utara', 'Ikan mungil berwarna biru-oranye psikedelik alami berkat pigmen seluler sejati.', 'Ikan mandarin adalah salah satu dari hanya dua spesies vertebrata yang diketahui menghasilkan pigmen biru sejati (cyanophore), bukan sekadar pembiasan cahaya struktural. Menjelang senja, pasangan ikan mandarin melakukan tarian pemijahan vertikal di atas laguna tenang.', 'Dilindungi oleh kelestarian habitat puing karang dangkal; rentan terhadap pengambilan untuk akuarium laut jika tidak dibudidayakan secara ex-situ.', 'assets/images/species/ikan-mandarin.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (14, 'Lionfish (Ikan Lepu Ayam)', 'Pterois volitans', 'lionfish', 1, 1, 5, 2, 55, 38, 'Ikan karang kecil dan udang malam', 'Tersebar alami di seluruh perairan Indonesia: Bunaken, Bali, Komodo, Maluku', 'Predator karang bersirip kipas elegan dengan duri punggung berbisa sebagai pertahanan.', 'Di perairan asli Indo-Pasifik termasuk Indonesia, lionfish memiliki predator alami seperti belut moray dan kerapu besar sehingga populasinya seimbang. Sirip dadanya yang menjuntai digunakan untuk menyudutkan mangsa sebelum menelannya utuh.', 'Berduri berbisa yang menyebabkan nyeri hebat bila tersentuh, namun merupakan bagian alami ekosistem terumbu karang Nusantara.', 'assets/images/species/lionfish.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (15, 'Gurita Karang Siang', 'Octopus cyanea', 'gurita', 4, 1, 5, 1, 45, 80, 'Kepiting, kerang, udang, dan ikan karang kecil', 'Wakatobi, Selat Lembeh, Bali, Flores, Maluku', 'Moluska cerdas ahli kamuflase yang mampu mengubah warna dan tekstur kulit dalam hitungan milidetik.', 'Berbeda dari kebanyakan gurita yang aktif malam hari, Octopus cyanea berburu pada siang hari di terumbu karang. Ia menggunakan sel kromatofora dan papila kulit untuk meniru warna karang, pasir, hingga meniru gerakan ikan lain saat melintasi area terbuka.', 'Populasi relatif stabil, tetapi penangkapan berlebihan di zona pasang surut dan kerusakan sarang karang dapat menekan kepadatan lokal.', 'assets/images/species/gurita.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (16, 'Cumi-cumi Sirip Besar', 'Sepioteuthis lessoniana', 'cumi-cumi', 4, 1, 5, 1, 100, 35, 'Ikan kecil dan udang pelagis dangkal', 'Perairan Jawa, Bali, Lombok, Sulawesi, Papua, Maluku', 'Cumi-cumi karang dengan sirip memanjang sepanjang mantel yang berkomunikasi lewat pola cahaya kulit.', 'Cumi-cumi sirip besar sering berenang berkelompok di atas terumbu karang dan padang lamun. Sepasang tentakel panjangnya dapat melesat menangkap mangsa dalam sekejap sementara pola garis dan bintik di kulitnya berubah untuk memberi sinyal ke sesama kawanan.', 'Bernilai ekonomi tinggi bagi nelayan pesisir Indonesia; pengelolaan alat tangkap ramah lingkungan menjaga ketersediaan kelompok telur yang menempel di karang mati dan lamun.', 'assets/images/species/cumi-cumi.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (17, 'Kima Raksasa', 'Tridacna gigas', 'kima-raksasa', 4, 1, 3, 1, 20, 120, 'Fotosintesis alga simbion (zooxanthellae) dan plankton terlarut', 'Wakatobi, Raja Ampat, Taka Bonerate, Kepulauan Karimunjawa, Maluku', 'Kerang bivalvia terbesar di dunia dengan mantel warna-warni penyaring air laut.', 'Kima raksasa hidup menetap di terumbu karang jernih dan memperoleh sebagian besar energinya dari alga mikroskopis zooxanthellae yang tinggal di jaringan mantelnya yang berwarna biru, hijau, atau cokelat keemasan. Individu dewasa dapat hidup lebih dari satu abad.', 'Dilindungi penuh oleh hukum Indonesia sejak lama karena cangkangnya kerap diburu untuk kerajinan dan dagingnya dikonsumsi. Program restocking kima aktif berjalan di beberapa taman nasional laut.', 'assets/images/species/kima-raksasa.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (18, 'Bintang Laut Bertanduk', 'Protoreaster nodosus', 'bintang-laut', 4, 2, 5, 1, 30, 30, 'Detritus organik, mikroalga, spons, dan invertebrata kecil', 'Kepulauan Seribu, Bangka Belitung, Sulawesi, Nusa Tenggara, Papua', 'Bintang laut ikonik padang lamun dangkal dengan barisan tonjolan kerucut gelap di lengannya.', 'Protoreaster nodosus hidup di dasar pasir dan padang lamun dangkal yang hangat. Tonjolan keras mirip tanduk di permukaan atas tubuhnya berfungsi sebagai pelindung alami dari pemangsa sekaligus memberi tampilan grafis kontras oranye-merah dan cokelat tua.', 'Meski belum masuk daftar terancam IUCN, pengumpulan bintang laut hidup untuk suvenir kering wisata pantai dapat menguras populasi dangkal secara drastis.', 'assets/images/species/bintang-laut.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (19, 'Teripang Pasir', 'Holothuria scabra', 'teripang', 4, 2, 2, 1, 20, 35, 'Detritus organik dan mikroorganisme dalam sedimen pasir laut', 'Sulawesi Tenggara, Maluku, Madura, Nusa Tenggara Barat, Papua', 'Pembersih dasar laut alami yang mengolah sedimen pasir padang lamun dan meningkatkan kualitas air.', 'Teripang pasir berperan seperti cacing tanah di darat: ia menelan pasir berbahan organik, mencerna bakteri dan detritus, lalu mengeluarkan pasir bersih yang kaya oksigen. Aktivitas ini mencegah pengasaman sedimen dasar di sekitar terumbu karang dan padang lamun.', 'Berstatus Terancam (Endangered) akibat eksploitasi komersial tinggi untuk komoditas trepang kering. Budidaya teripang pasir oleh masyarakat pesisir terus dikembangkan sebagai solusi lestari.', 'assets/images/species/teripang.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (20, 'Lobster Mutiara', 'Panulirus ornatus', 'lobster-mutiara', 4, 1, 5, 1, 50, 50, 'Kerang, kepiting kecil, cacing laut, dan bangkai organik', 'Perairan Selatan Jawa, Lombok, Sumbawa, Aceh, Maluku, Papua', 'Lobster karang berukuran besar dengan karapas bercorak batik biru-hijau dan belang kaki mencolok.', 'Lobster mutiara adalah spesies lobster berduri terbesar di perairan tropis Indonesia. Pada siang hari mereka berlindung di celah gua karang dengan sepasang antena panjang menjulur keluar untuk mendeteksi bahaya, lalu keluar mencari makan pada malam hari.', 'Regulasi ukuran minimum tangkap dan larangan penangkapan lobster bertelur diterapkan di Indonesia untuk menjaga keberlanjutan stok benih bening lobster di alam.', 'assets/images/species/lobster-mutiara.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (21, 'Kepiting Bakau', 'Scylla serrata', 'kepiting-bakau', 4, 3, 5, 0, 10, 24, 'Moluska, ikan kecil, krustasea, dan materi organik hutan bakau', 'Tarakan (Kalimantan Utara), Cilacap, Papua, Sumatera Timur, Sulawesi', 'Krustasea tangguh penghuni lumpur hutan mangrove yang toleran terhadap perubahan salinitas.', 'Kepiting bakau menggali liang di antara akar mangrove dan memainkan peran penting dalam daur ulang nutrien ekosistem pasang surut. Sepasang capitnya yang kuat mampu memecahkan cangkang kerang bakau dengan mudah.', 'Menjadi komoditas perikanan pesisir bernilai tinggi; pelestarian hutan mangrove dan pembatasan penangkapan betina bertelur sangat penting untuk menjaga populasinya.', 'assets/images/species/kepiting-bakau.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (22, 'Nautilus Berbilik', 'Nautilus pompilius', 'nautilus', 4, 4, 4, 100, 700, 20, 'Krustasea laut dalam, ikan kecil, dan bangkai dasar lereng karang', 'Laut Banda, Maluku, Nusa Tenggara Timur, Sulawesi Utara', 'Fosil hidup purba bercangkang spiral logaritmik yang mengapung di lereng laut dalam.', 'Nautilus telah menghuni samudra bumi selama lebih dari 450 juta tahun. Cangkangnya terbagi menjadi puluhan bilik berisi campuran gas dan cairan untuk mengatur daya apung secara presisi saat bermigrasi naik ke lereng karang pada malam hari.', 'Dilindungi penuh berdasarkan hukum Indonesia (Permen LHK No. P.106/2018) karena tingkat perkembangbiakan sangat lambat serta perburuan cangkang mutiaranya.', 'assets/images/species/nautilus.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (23, 'Belut Moray Raksasa', 'Gymnothorax javanicus', 'belut-moray', 1, 1, 5, 1, 50, 240, 'Ikan karang, gurita, dan krustasea malam hari', 'Komodo, Bunaken, Tulamben, Alor, Raja Ampat', 'Predator penyergap bertubuh panjang penghuni celah terumbu karang dengan dua pasang rahang.', 'Belut moray raksasa merupakan spesies moray terbesar berdasarkan massa tubuh. Di dalam tenggorokannya terdapat rahang faring kedua yang maju untuk menarik mangsa ke saluran pencernaan. Sering terlihat berburu kooperatif bersama ikan kerapu.', 'Memiliki peran penting mengontrol populasi ikan dan kepiting di terumbu karang. Meski tampak mengintimidasi saat membuka mulut, gerakan itu adalah cara alami memompa air melalui insang.', 'assets/images/species/belut-moray.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (24, 'Ikan Kerapu Malabar', 'Epinephelus malabaricus', 'ikan-kerapu', 1, 1, 5, 2, 150, 120, 'Ikan karang, krustasea, dan sefalopoda', 'Kepulauan Riau, Lampung, Sulawesi, Bali, Maluku, Papua', 'Ikan predator karang bernilai ekonomi tinggi dengan pola belang cokelat samar dan bintik gelap.', 'Kerapu malabar menghuni terumbu karang berbatu, muara estuari, hingga hutan mangrove saat muda. Sebagai hermafrodit protogini, individu muda berjenis kelamin betina lalu sebagian berubah menjadi jantan ketika mencapai ukuran besar.', 'Tekanan tangkap pada ikan kerapu besar dapat mengganggu keseimbangan rasio jantan-betina di alam. Pembesaran kerapu melalui keramba jaring apung berkelanjutan terus didorong.', 'assets/images/species/ikan-kerapu.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (25, 'Ikan Kakap Merah Karang', 'Lutjanus bohar', 'ikan-kakap', 1, 1, 5, 4, 180, 90, 'Ikan karang, udang, kepiting, dan amfipoda', 'Tersebar luas di perairan Indonesia bagian barat hingga timur', 'Ikan kakap karang berumur panjang hingga 50 tahun yang berpatroli di tubir terumbu luar.', 'Lutjanus bohar hidup soliter maupun dalam gerombolan kecil di sekitar lereng karang terjal yang dialiri arus jernih. Ikan dewasa memiliki tubuh merah kecokelatan gelap dengan gigi taring mencolok untuk menangkap mangsa cepat.', 'Karena usianya sangat panjang dan baru dewasa pada umur belasan tahun, penangkapan selektif ukuran sangat diperlukan agar populasi induk tetap terjaga.', 'assets/images/species/ikan-kakap.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (26, 'Ikan Tuna Sirip Kuning', 'Thunnus albacares', 'ikan-tuna', 1, 4, 5, 1, 250, 200, 'Ikan terbang, makarel, cumi-cumi, dan krustasea pelagis', 'Laut Banda, Laut Sulawesi, Samudra Hindia Selatan Jawa, Laut Maluku', 'Perenang cepat samudra bermigrasi jauh dengan sirip punggung dan anal kuning cerah memanjang.', 'Tuna sirip kuning mampu berenang dengan kecepatan tinggi menempuh ribuan kilometer melintasi perairan laut dalam Nusantara. Tubuhnya berbentuk torpedo hidrodinamis dengan sistem sirkulasi otot hangat yang memberi tenaga jelajah luar biasa.', 'Menjadi komoditas ekspor perikanan utama Indonesia; penerapan alat tangkap pancing ulur (handline) dan pole-and-line membantu menjaga kelestarian stok tuna serta meminimalkan tangkapan sampingan.', 'assets/images/species/ikan-tuna.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (27, 'Pari Elang Tutul', 'Aetobatus ocellatus', 'pari-elang', 2, 1, 3, 1, 60, 300, 'Kerang, siput laut, kepiting, dan cacing dasar pasir', 'Raja Ampat, Komodo, Wakatobi, Bali, Kepulauan Bangka Belitung', 'Pari pelagis pesisir bercorak bintik putih di punggung gelap dengan ekor cambuk panjang.', 'Pari elang tutul sering berenang anggun di dekat permukaan maupun di atas hamparan pasir terumbu karang, mengepakkan sepasang sirip dadanya yang runcing menyerupai sayap burung elang. Rahangnya memiliki lempeng gigi datar kuat untuk menghancurkan cangkang kerang.', 'Berstatus Rentan (Vulnerable) karena laju reproduksi rendah (1–4 anak per kelahiran) dan kerap tertangkap jaring insang pesisir.', 'assets/images/species/pari-elang.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (28, 'Penyu Sisik', 'Eretmochelys imbricata', 'penyu-sisik', 3, 1, 1, 1, 30, 90, 'Spons laut beracun, anemon, dan alga karang', 'Kepulauan Seribu, Belitung, Bunaken, Anambas, Raja Ampat, Derawan', 'Penyu terumbu karang berparuh runcing mirip elang yang kini berstatus Kritis akibat perburuan karapas.', 'Penyu sisik berperan menjaga keberagaman terumbu karang dengan memakan spons laut kompetitor yang dapat menutupi pertumbuhan karang keras. Paruhnya yang sempit dan melengkung dirancang khusus untuk menjangkau celah karang.', 'Berstatus Kritis (Critically Endangered) akibat perdagangan ilegal karapas sisik bermotif marmer. Penjagaan pulau peneluran dan edukasi masyarakat pesisir menjadi garda terdepan penyelamatannya.', 'assets/images/species/penyu-sisik.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (29, 'Penyu Lekang', 'Lepidochelys olivacea', 'penyu-lekang', 3, 4, 3, 5, 150, 70, 'Ubur-ubur, kepiting, udang, tunikata, dan siput laut', 'Pantai Samas (Yogyakarta), Alas Purwo, Trenggalek, Bali, Lampung, Maluku', 'Spesies penyu laut terkecil dengan karapas berbentuk hati berwarna hijau zaitun keabuan.', 'Penyu lekang banyak ditemukan bertelur di pantai berpasir hitam pesisir selatan Jawa dan Bali. Berbeda dari penyu hijau yang herbivora, penyu lekang adalah omnivora yang lebih menyukai kepiting, udang, serta ubur-ubur di perairan lepas pantai.', 'Dilindungi penuh di Indonesia; puluhan kelompok konservasi pantai berbasis warga (pokmaswas) aktif merelokasi sarang telur dari ancaman predator dan pasang tinggi.', 'assets/images/species/penyu-lekang.jpg', 0);
INSERT INTO species (id, common_name, scientific_name, slug, category_id, habitat_id, conservation_status_id, depth_min_m, depth_max_m, length_cm, diet, distribution_indonesia, summary, description, conservation_notes, image_url, is_featured) VALUES (30, 'Karang Keras (Scleractinia)', 'Acropora cervicornis / Scleractinia', 'karang-keras', 5, 1, 3, 1, 40, 150, 'Alga simbion zooxanthellae dan zooplankton malam hari', 'Seluruh gugusan terumbu karang Segitiga Terumbu Karang Indonesia', 'Arsitek utama terumbu karang yang membentuk kerangka kalsium karbonat bagi jutaan biota laut.', 'Karang keras (ordo Scleractinia) terdiri atas koloni ribuan polip mungil yang mengekskresikan kerangka kapur kalsium karbonat. Struktur bercabang dan masifnya menciptakan rumah, tempat berlindung, dan lokasi pemijahan bagi seperempat dari seluruh spesies ikan laut di bumi.', 'Sangat rentan terhadap kenaikan suhu muka laut yang memicu pemutihan karang (coral bleaching), pengasaman laut, serta praktik penangkapan ikan destruktif.', 'assets/images/species/karang-keras.jpg', 1);
INSERT INTO educational_materials (id, title, slug, topic, reading_minutes, author_name, summary, content, image_url) VALUES (1, 'Segitiga Terumbu Karang: Jantung Keanekaragaman Hayati Laut Dunia', 'segitiga-terumbu-karang-indonesia', 'Ekologi Terumbu Karang', 6, 'Dr. Nabila Pratiwi', 'Mengapa perairan Indonesia Timur menyimpan lebih dari 76% spesies karang dunia dan ribuan spesies ikan karang endemik.', 'Indonesia menempati posisi inti dalam kawasan Segitiga Terumbu Karang (Coral Triangle) yang membentang dari perairan Raja Ampat, Laut Banda, Bunaken, hingga Wakatobi. Pertemuan arus lintas Samudra Pasifik dan Samudra Hindia (Arlindo) membawa nutrien hangat serta menyebarkan larva karang dan ikan ke ribuan pulau.\n\nLebih dari 590 spesies karang pembentuk terumbu dan lebih dari 2.200 spesies ikan karang tercatat hidup di wilayah ini. Selain menjadi penyangga ekonomi perikanan berkelanjutan bagi jutaan masyarakat pesisir, terumbu karang sehat meredam hingga 97% energi gelombang badai sebelum mencapai daratan.\n\nPelestarian terumbu karang menuntut penghentian penangkapan ikan dengan bom dan sianida, pengendalian limbah sedimen dari darat, serta penerapan zonasi kawasan konservasi perairan (KKP) yang adil bagi nelayan lokal.', 'assets/images/education/edukasi-terumbu.jpg');
INSERT INTO educational_materials (id, title, slug, topic, reading_minutes, author_name, summary, content, image_url) VALUES (2, 'Mengenal Siklus Hidup & Konservasi Penyu Laut Nusantara', 'siklus-hidup-konservasi-penyu-nusantara', 'Konservasi Megafauna', 5, 'Budi Santoso, M.Si.', 'Dari penetasan di pasir pantai hingga migrasi lintas samudra: enam dari tujuh spesies penyu dunia hidup di Indonesia.', 'Dari tujuh spesies penyu laut yang tersisa di bumi, enam di antaranya berenang dan bertelur di perairan Indonesia: penyu hijau, penyu sisik, penyu lekang, penyu belimbing, penyu tempayan, dan penyu pipih.\n\nSuhu pasir sarang menentukan jenis kelamin tukik yang menetas: pasir yang lebih hangat cenderung menghasilkan lebih banyak betina, sementara pasir yang lebih sejuk menghasilkan jantan. Perubahan iklim yang menaikkan suhu pesisir kini menjadi tantangan baru bagi keseimbangan rasio kelamin penyu.\n\nPartisipasi aktif masyarakat pesisir dalam menjaga pantai peneluran di Pangumbahan, Sukamade, Derawan, dan Bali Selatan terbukti mampu meningkatkan tingkat penetasan tukik hingga di atas 80%.', 'assets/images/education/edukasi-penyu.jpg');
INSERT INTO educational_materials (id, title, slug, topic, reading_minutes, author_name, summary, content, image_url) VALUES (3, 'Raja Ampat & Arsitektur Kawasan Konservasi Perairan Indonesia', 'raja-ampat-kawasan-konservasi-perairan', 'Pengelolaan Ekosistem', 7, 'Siti Rahmawati', 'Bagaimana kearifan lokal Sasi Laut berpadu dengan sains modern untuk memulihkan populasi hiu, pari manta, dan ikan karang.', 'Kawasan Konservasi Perairan (KKP) di Papua Barat, khususnya Raja Ampat, menjadi contoh global keberhasilan pemulihan biomassa ikan karang melalui integrasi hukum adat Sasi Laut dan pemantauan ilmiah berkala.\n\nMelalui sistem zonasi—mulai dari zona inti larang ambil (no-take zone) hingga zona pemanfaatan perikanan tradisional—ikan induk berukuran besar seperti napoleon wrasse dan kerapu dapat bereproduksi optimal dan melimpahkan benihnya ke area tangkap nelayan di sekitarnya (efek spillover).\n\nData pemantauan jangka panjang menunjukkan peningkatan signifikan penampakan pari manta dan hiu karang di kawasan yang dikelola bersama masyarakat adat.', 'assets/images/education/edukasi-konservasi.jpg');
INSERT INTO educational_materials (id, title, slug, topic, reading_minutes, author_name, summary, content, image_url) VALUES (4, 'Ancaman Sampah Plastik & Jaring Hantu di Ekosistem Laut Tropis', 'ancaman-sampah-plastik-laut-tropis', 'Ancaman & Solusi Laut', 5, 'Andi Wijaya', 'Dampak mikroplastik dan ghost net terhadap penyu, dugong, serta rantai makanan pesisir, beserta langkah pencegahan konkret.', 'Setiap tahun, jutaan ton plastik memasuki lautan dunia, dan sebagian besar terbawa arus menuju perairan pesisir dan palung laut. Bagi penyu hijau dan penyu lekang, kantong plastik bening yang melayang di kolom air kerap terlihat identik dengan ubur-ubur—makanan alami mereka.\n\nSelain plastik sekali pakai, jaring ikan yang hilang atau dibuang di laut (ghost net) terus menjerat hiu karang, pari, dan merusak koloni karang keras selama bertahun-tahun.\n\nLangkah nyata yang dapat diterapkan dimulai dari pengelolaan sampah berbasis sumber di kota pesisir, pengurangan plastik sekali pakai, serta gerakan pembersihan jaring hantu oleh komunitas penyelam konservasi.', 'assets/images/education/edukasi-plastik.jpg');
INSERT INTO quizzes (id, title, slug, description, difficulty, time_limit_minutes) VALUES (1, 'Eksplorasi Megafauna Laut Indonesia', 'megafauna-laut-indonesia', 'Uji pengetahuanmu mengenai hiu paus, pari manta, dugong, penyu, dan ikan mola-mola yang menghuni perairan Nusantara.', 'Pemula', 8);
INSERT INTO quizzes (id, title, slug, description, difficulty, time_limit_minutes) VALUES (2, 'Ekosistem Terumbu Karang & Simbiosis Laut', 'ekosistem-terumbu-karang', 'Pelajari hubungan unik antar spesies di Segitiga Terumbu Karang Dunia serta peran ekologis masing-masing biota.', 'Menengah', 10);
INSERT INTO quizzes (id, title, slug, description, difficulty, time_limit_minutes) VALUES (3, 'Status Konservasi & Perlindungan Biota Nusantara', 'konservasi-biota-nusantara', 'Tantangan lanjutan mengenai status IUCN, hukum perlindungan satwa laut Indonesia, dan solusi pelestarian.', 'Lanjutan', 10);
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 1, 'Apa sumber makanan utama Hiu Paus (Rhincodon typus) meskipun tubuhnya dapat mencapai panjang 12 meter?', 'Ikan tuna dan lumba-lumba', 'Plankton, krill, dan ikan kecil dengan cara menyaring air', 'Terumbu karang keras dan spons laut', 'Kepiting bakau dan kerang kima', 'B', 'Hiu paus adalah pemakan saring (filter feeder) yang jinak dan hanya menyaring plankton, krill, serta ikan pelagis kecil.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 1, 'Di antara ciri berikut, manakah yang membedakan setiap individu Pari Manta Samudra (Mobula birostris) bagi para peneliti?', 'Panjang ekornya yang berbeda setiap musim', 'Pola bercak hitam unik di bagian perutnya', 'Warna matanya yang berubah saat dewasa', 'Jumlah sirip punggungnya', 'B', 'Pola bintik hitam di sisi ventral (perut) pari manta bersifat unik seperti sidik jari manusia dan dipakai untuk identifikasi individu.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 1, 'Ekosistem apakah yang menjadi sumber pakan utama sekaligus habitat hidup Dugong (Dugong dugon)?', 'Palung laut dalam lebih dari 1.000 meter', 'Padang lamun (seagrass meadow) pesisir jernih', 'Terumbu karang curam berarus deras', 'Muara sungai air tawar murni', 'B', 'Dugong adalah mamalia laut herbivora sejati yang bergantung penuh pada hamparan padang lamun sebagai sumber pakan.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 1, 'Mengapa Penyu Hijau (Chelonia mydas) mendapat nama "penyu hijau"?', 'Karena tempurung punggungnya selalu berwarna hijau neon', 'Karena warna lemak tubuh kehijauan akibat memakan lamun dan alga', 'Karena matanya memancarkan cahaya hijau di malam hari', 'Karena hanya hidup di hutan mangrove hijau', 'B', 'Penyu hijau dewasa bersifat herbivora pemakan lamun dan alga laut sehingga lapisan lemak di bawah karapasnya berwarna kehijauan.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 1, 'Di perairan Indonesia manakah Ikan Mola-mola (Mola alexandrini) paling terkenal muncul pada musim arus dingin Juli–Oktober?', 'Laut Jawa bagian utara', 'Nusa Penida dan Selat Lombok', 'Muara Sungai Musi', 'Danau Sentani', 'B', 'Perairan Nusa Penida (seperti Crystal Bay) menjadi lokasi ikonik kemunculan ikan mola-mola saat arus dingin naik ke stasiun pembersihan karang.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (6, 2, 'Alga mikroskopis apakah yang bersimbiosis di dalam jaringan Karang Keras dan Kima Raksasa untuk menghasilkan energi lewat fotosintesis?', 'Fitoplankton Diatom', 'Zooxanthellae', 'Sargassum pelagis', 'Sianobakteria dasar laut', 'B', 'Zooxanthellae memberikan warna indah sekaligus menyuplai sebagian besar energi karbohidrat bagi karang pembentuk terumbu dan kima raksasa.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (7, 2, 'Peran ekologis penting apakah yang dijalankan Napoleon Wrasse (Cheilinus undulatus) bagi kesehatan terumbu karang?', 'Memangsa bintang laut mahkota berduri pemakan karang', 'Menghasilkan oksigen langsung di dasar pasir', 'Menyaring minyak mentah di permukaan laut', 'Membentuk akar penyangga di zona pasang surut', 'A', 'Napoleon wrasse adalah salah satu predator alami bintang laut mahkota berduri (Acanthaster planci) yang merusak karang jika meledak populasinya.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (8, 2, 'Bagaimana Ikan Badut (Amphiprion ocellaris) terlindung dari sengatan tentakel anemon laut?', 'Ia hanya berenang di malam hari saat anemon tidur', 'Ia memiliki lapisan lendir khusus yang mencegah pemicuan sengat anemon', 'Ia memakan seluruh tentakel anemon terlebih dahulu', 'Ia memiliki sisik besi yang sangat tebal', 'B', 'Lapisan mukus unik pada kulit ikan badut tidak memicu sel penyengat (nematocyst) pada tentakel anemon.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (9, 2, 'Manakah spesies yang berperan mengolah serta membersihkan sedimen pasir padang lamun seperti cacing tanah di lautan?', 'Teripang Pasir (Holothuria scabra)', 'Cumi-cumi Sirip Besar', 'Hiu Martil Bergerigi', 'Nautilus Berbilik', 'A', 'Teripang pasir menelan sedimen dasar, mencerna bahan organik berlebih, dan mengeluarkan pasir bersih yang menjaga aerasi dasar laut.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (10, 2, 'Apa keunggulan utama Ikan Mandarin (Synchiropus splendidus) yang menjadikannya unik di antara vertebrata?', 'Mampu hidup di air tawar dan laut dalam', 'Menghasilkan pigmen biru sejati melalui sel cyanophore', 'Berukuran lebih besar dari hiu karang', 'Memiliki cangkang spiral keras', 'B', 'Ikan mandarin adalah salah satu dari sangat sedikit vertebrata yang memiliki sel pigmen biru sejati (cyanophore).');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (11, 3, 'Manakah pasangan spesies biota laut Indonesia berikut yang saat ini berstatus Kritis (Critically Endangered) menurut IUCN?', 'Ikan Badut dan Kepiting Bakau', 'Penyu Sisik dan Hiu Martil Bergerigi', 'Lobster Mutiara dan Pari Totol Biru', 'Cumi-cumi dan Ikan Tuna Sirip Kuning', 'B', 'Penyu sisik (Eretmochelys imbricata) dan Hiu martil bergerigi (Sphyrna lewini) berstatus Kritis karena eksploitasi berat dan penurunan populasi drastis.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (12, 3, 'Faktor alami apakah yang menentukan jenis kelamin tukik penyu laut selama masa inkubasi di dalam sarang pasir?', 'Kadar garam air laut terdekat', 'Suhu pasir di sekitar sarang selama masa inkubasi', 'Fase bulan saat induk bertelur', 'Warna cangkang induk penyu', 'B', 'Penyu memiliki penentuan jenis kelamin bergantung suhu (TSD): suhu lebih hangat menghasilkan lebih banyak betina.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (13, 3, 'Mengapa Nautilus Berbilik (Nautilus pompilius) disebut sebagai "fosil hidup" yang sangat rentan terhadap perburuan cangkang?', 'Karena ia hanya hidup di sungai Kalimantan', 'Karena ia tidak berubah banyak selama ratusan juta tahun dan laju reproduksinya sangat lambat', 'Karena tubuhnya mengeluarkan cahaya neon', 'Karena bertelur jutaan butir setiap minggu', 'B', 'Nautilus tumbuh sangat lambat dan hanya menghasilkan sedikit telur per tahun sehingga populasinya sulit pulih bila diburu.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (14, 3, 'Apa istilah kearifan lokal di Papua dan Maluku berupa larangan mengambil hasil laut sementara untuk pemulihan ekosistem?', 'Subak', 'Sasi Laut', 'Terasering', 'Gugur Gunung', 'B', 'Sasi Laut merupakan aturan adat masyarakat Maluku dan Papua yang menutup sementara pengambilan biota tertentu agar populasinya pulih.');
INSERT INTO quiz_questions (id, quiz_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (15, 3, 'Pada famili kuda laut (Hippocampus spp.), siapakah yang membawa dan mengerami telur hingga menetas?', 'Kuda laut betina di dalam mulutnya', 'Kuda laut jantan di dalam kantung pengeraman perutnya', 'Keduanya menempelkan telur pada teripang pasir', 'Telur mengapung bebas di permukaan samudra', 'B', 'Kuda laut betina menitipkan telur ke kantung pengeraman (brood pouch) milik pejantan hingga menetas menjadi anak kuda laut mandiri.');
INSERT INTO quiz_results (id, user_id, quiz_id, score, total_questions, percentage) VALUES (1, 2, 1, 4, 5, 80);
INSERT INTO quiz_results (id, user_id, quiz_id, score, total_questions, percentage) VALUES (2, 2, 2, 5, 5, 100);

-- Tips Konservasi

CREATE TABLE conservation_tips (
  id INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(160) NOT NULL,
  category VARCHAR(60) NOT NULL,
  icon VARCHAR(30) NOT NULL DEFAULT 'daun',
  difficulty ENUM('Mudah','Sedang','Menantang') NOT NULL DEFAULT 'Mudah',
  summary VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  related_species_id INT NULL,
  related_habitat_id INT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_tip_species FOREIGN KEY (related_species_id) REFERENCES species(id) ON DELETE SET NULL,
  CONSTRAINT fk_tip_habitat FOREIGN KEY (related_habitat_id) REFERENCES habitats(id) ON DELETE SET NULL
) ENGINE=InnoDB;

INSERT INTO conservation_tips (title, category, icon, difficulty, summary, description, related_species_id, related_habitat_id, sort_order) VALUES
('Kurangi plastik sekali pakai', 'Sehari-hari', 'plastik', 'Mudah',
 'Bawa tas, botol, dan sedotan sendiri untuk mengurangi sampah yang berakhir di laut.',
 'Kantong plastik yang melayang di air sering dikira ubur-ubur oleh penyu dan tertelan. Membawa tas belanja, botol minum, dan alat makan sendiri adalah cara paling mudah untuk mengurangi sampah plastik yang mengalir lewat sungai dan selokan menuju laut.',
 (SELECT id FROM species WHERE slug='penyu-hijau'), 2, 1),
('Pilih tabir surya yang lebih ramah karang', 'Wisata Bahari', 'matahari', 'Mudah',
 'Gunakan tabir surya berbahan mineral dan pakai baju selam berlengan panjang saat snorkeling.',
 'Beberapa bahan kimia tabir surya, seperti oxybenzone dan octinoxate, dikaitkan dengan stres pada karang. Pilih produk berbahan mineral (zinc oxide atau titanium dioxide), oleskan sebelum turun ke air, dan kenakan rash guard agar kebutuhan tabir surya berkurang.',
 (SELECT id FROM species WHERE slug='karang-keras'), 1, 2),
('Jangan menyentuh atau menginjak karang', 'Wisata Bahari', 'karang', 'Mudah',
 'Satu sentuhan bisa melukai polip karang yang tumbuh sangat lambat.',
 'Karang adalah hewan hidup yang tumbuh hanya beberapa sentimeter per tahun. Jaga daya apung saat menyelam atau snorkeling, jangan berdiri di atas karang, dan jangan mengambil karang atau kerang sebagai kenang-kenangan.',
 (SELECT id FROM species WHERE slug='karang-keras'), 1, 3),
('Jaga jarak dan jangan memberi makan satwa laut', 'Wisata Bahari', 'mata', 'Mudah',
 'Amati dari jauh, tanpa menyentuh, mengejar, atau menunggangi satwa laut.',
 'Satwa yang terlalu sering didekati bisa stres, berubah perilaku, atau terluka oleh baling-baling perahu. Ikuti arahan pemandu setempat, jangan menyentuh atau menunggangi hewan, jangan memberi makan, dan matikan lampu kilat saat memotret.',
 (SELECT id FROM species WHERE slug='hiu-paus'), 4, 4),
('Pilih seafood yang ditangkap secara berkelanjutan', 'Konsumen', 'ikan', 'Sedang',
 'Tanyakan asal ikan dan pilih yang ditangkap dengan alat selektif.',
 'Penangkapan berlebihan menurunkan stok ikan dan merusak rantai makanan laut. Pilih ikan dari nelayan yang menggunakan alat tangkap selektif seperti pancing, hindari ikan yang masih muda atau sedang bertelur, dan tanyakan asal-usul ikan saat membeli.',
 (SELECT id FROM species WHERE slug='ikan-tuna'), 4, 5),
('Tolak suvenir dari satwa laut', 'Konsumen', 'larangan', 'Mudah',
 'Jangan membeli hiasan dari sisik penyu, karang, atau cangkang kerang langka.',
 'Perhiasan dari sisik penyu, awetan hewan laut, dan karang hias mendorong perburuan. Banyak satwa laut, termasuk penyu, dilindungi hukum Indonesia. Pilih suvenir dari bahan lain dan laporkan jika menemukan penjualannya.',
 (SELECT id FROM species WHERE slug='penyu-sisik'), 1, 6),
('Tanam dan lindungi mangrove', 'Pesisir', 'mangrove', 'Menantang',
 'Mangrove menahan abrasi dan menjadi tempat bertumbuh bagi banyak anak ikan.',
 'Hutan mangrove melindungi garis pantai dari gelombang, menyimpan karbon, dan menjadi tempat pembesaran ikan, udang, dan kepiting. Ikut penanaman bersama komunitas lokal, jangan menebang, dan pastikan jenis serta lokasi tanam sesuai arahan pengelola setempat.',
 (SELECT id FROM species WHERE slug='kepiting-bakau'), 3, 7),
('Ikut bersih pantai dan pilah sampah', 'Komunitas', 'sampah', 'Mudah',
 'Bersihkan pantai bersama-sama dan pilah sampah dari rumah.',
 'Aksi bersih pantai menyelamatkan satwa dari jerat dan tertelan sampah, tetapi hasil terbaik datang dari mengurangi sampah di sumbernya. Catat jenis sampah yang ditemukan agar komunitas tahu penyebab utamanya, dan pilah sampah rumah tangga agar tidak terbawa ke saluran air.',
 (SELECT id FROM species WHERE slug='lumba-lumba'), 2, 8),
('Gunakan jangkar dengan bijak', 'Wisata Bahari', 'jangkar', 'Sedang',
 'Jangkar yang jatuh di padang lamun atau karang bisa merusak habitat dalam sekejap.',
 'Padang lamun adalah sumber makanan dugong dan penyu hijau. Pakai pelampung tambat (mooring buoy) bila tersedia, jangkarkan perahu di dasar pasir, dan jangan menyeret jangkar di atas lamun atau karang.',
 (SELECT id FROM species WHERE slug='dugong'), 2, 9),
('Hemat energi untuk menjaga suhu laut', 'Sehari-hari', 'energi', 'Sedang',
 'Pemanasan laut memicu pemutihan karang, jadi hemat listrik dan kurangi emisi.',
 'Kenaikan suhu laut membuat karang mengeluarkan alga simbiosisnya sehingga memutih dan bisa mati. Mengurangi pemakaian listrik, memilih transportasi yang lebih efisien, dan mendukung energi bersih ikut membantu memperlambat pemanasan.',
 (SELECT id FROM species WHERE slug='ikan-badut'), 1, 10),
('Laporkan penyu bertelur atau satwa terdampar', 'Komunitas', 'telepon', 'Sedang',
 'Hubungi pihak berwenang setempat, jangan memindahkan telur atau hewan sendiri.',
 'Jika menemukan penyu bertelur, tukik, atau satwa laut terdampar, jaga jarak, redam cahaya dan keramaian, lalu hubungi BKSDA, dinas kelautan dan perikanan, atau komunitas konservasi setempat. Penanganan yang salah justru bisa membahayakan hewan tersebut.',
 (SELECT id FROM species WHERE slug='penyu-lekang'), 4, 11),
('Dukung komunitas konservasi dan sains warga', 'Komunitas', 'komunitas', 'Mudah',
 'Bagikan foto dan catatan pengamatan, atau jadi relawan program pemantauan.',
 'Data dari penyelam, nelayan, dan wisatawan membantu peneliti memantau populasi satwa laut, misalnya lewat foto pola bintik hiu paus untuk identifikasi individu. Ikuti program resmi, bagikan pengamatan dengan lokasi dan tanggal, dan dukung lembaga konservasi lokal.',
 (SELECT id FROM species WHERE slug='hiu-paus'), 4, 12);
